quests[52252] = { id = 52252, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein explosiver Auftritt", description = "Ein schicker Hut und etwas Überredungskunst werden diesmal nicht reichen, um uns nach Freihafen reinzuschmuggeln, also habe ich an Sprengstoff gedacht. Weiter habe ich mir gedacht, dass wir diesen von Aschenwind stehlen. Das wäre schließlich nur gerecht! Sie nimmt sich etwas von Lady Katherine, also nehmen wir uns ein paar azeritverstärkte Granaten von Aschenwind.\n\nNa schön, vielleicht ist es nicht ganz dasselbe, aber Ihr wisst schon, was ich meine.\n\nMacht Euch auf zur Aschenwindgießerei und schnappt Euch die größten Azeritgranaten, die Ihr kriegen könnt.\n\nIch werde mich derweil um Luftunterstützung kümmern.", sourceObjective = "Sammelt 100 große Azeritgranaten in der Aschenwindgießerei.", progress = "Gut gemacht! Die werden einschlagen wie eine Bombe! Sozusagen.", completion = "Ihr habt die Munition und ich die Luftunterstützung.\n\n<Finn deutet grinsend auf Taelia und Sturmherz.>\n\nIhr wisst, worauf ich hinauswill.", sourceObjectiveStatus = "unverified-source-field" }
quests[52253] = { id = 52253, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlüssel zum Erfolg in Freihafen", description = "Jeder weiß, dass ich einer Wette selten abgeneigt bin, und ich würde einiges darauf setzen, dass die Informationen, auf die wir aus sind, in der Schließkassette von Harlan dem Schmierigen zu finden sind. Sie wären viel zu kostbar, um sie anderswo zu lagern. Ich wette, die Kassette steht immer noch da. Das Problem sind die Sicherheitsvorkehrungen.\n\nWisst Ihr, man braucht drei Schlüssel für die Kassette, und er hat jeden davon einem anderen Leutnant gegeben. Wir müssen sie uns holen.\n\nAber mit Euren Fertigkeiten, meiner List und Taelias Luftunterstützung wird das ein Kinderspiel.", sourceObjective = "Beschafft die Schlüssel von Leutnants der Eisenfluträuber.", progress = "Schön gemacht! Seht Ihr? Ich wusste doch, dass diese Eisenfluträuber Euch keine Probleme machen würden.", completion = "Gut, die Schlüssel hätten wir. Jetzt müssen wir nur noch die Kassette in die Finger bekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[52256] = { id = 52256, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Malfurions Rückkehr", description = "Hört Ihr seine Stimme?\n\nMalfurion erbittet unsere Hilfe! Nur Mut, {name}. Die Ahnen stehen heute an Eurer Seite.", sourceObjective = "Sucht Malfurion an den Wildschnellen.", completion = "Wir müssen sie zurückdrängen!", sourceObjectiveStatus = "unverified-source-field" }
quests[52257] = { id = 52257, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Felsenwelt", description = "Wir kämpfen nicht allein, {name}.\n\nHeute werden die Urtume Euch auf ihren Ästen tragen. Gebt alles, um unsere Wälder zu verteidigen!", sourceObjective = "Schließt Euch den Urtumen an, um die Feinde der Horde zu töten.", completion = "Wir müssen sie aufhalten!", sourceObjectiveStatus = "unverified-source-field" }
quests[52258] = { id = 52258, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit Muscheln muss man manchmal meckern", description = "Papa wollte angeln gehen und Mama arbeitet, also hat er mich mitgenommen.\n\nAber mir ist langweilig! Ich möchte ein paar Muscheln verkaufen, die ich am Strand angespült gefunden habe, aber niemand interessiert sich für sie. Sie sind wohl nicht hübsch genug...\n\nIhr scheint keine Angst vor den riesigen Schlangen am Strand zu haben. Könnt Ihr mir ein paar hübschere Muscheln bringen? Und bitte nur die glänzendsten!", sourceObjective = "Sammelt Muscheln für Jenny.", progress = "Kommt, feilschen wir... Wie war das? Klinge ich wie eine echte Muschelverkäuferin?", completion = "Oooh! Sind die hübsch! Ich wette, die werden sich wie warme Semmeln verkaufen.", sourceObjectiveStatus = "unverified-source-field" }
quests[52259] = { id = 52259, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf dass ihm die Lust vergehe", description = "Ich wusste ja, dass Gallywix selbstsüchtig und verschwenderisch ist, aber das... das geht einfach zu weit.\n\nSeine Überheblichkeit nimmt Ausmaße an, die jegliche Führungsqualitäten im Keim ersticken. Er hortet den Reichtum der Leute, um seine Maßlosigkeit, Gier und seine Begierden zu befriedigen, während die Leute unter ihm sich abmühen müssen.\n\nUnd was vielleicht noch schlimmer ist, die Salonlöwen der Horde feiern diese Verworfenheit.\n\nAlle Völker von Azeroth verdienen etwas Besseres. Wir müssen diesen verwöhnten Feiglingen eine Lektion erteilen.", sourceObjective = "Schleicht Euch bei Gallywix' Party ein.", progress = "Wie können sie so in Saus und Braus leben, während ihre Leute Not leiden?", completion = "Ich werde nicht behaupten, dass dies all die Probleme der Goblins lösen könnte, aber es ist schon eine schöne Sache, diese aufgeblasenen Parasiten ein wenig zur Rechenschaft zu ziehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[52260] = { id = 52260, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die Ecke gedrängt", description = "Habt Ihr gehört, wie Gallywix seinen Dienern und Handlangern Befehle zugebrüllt hat? Er ist immer noch mit Frivolitäten beschäftigt, obwohl wir vor seinem Tor stehen.\n\nIn seinem maßlosen Prunkpalast fühlt er sich sicher. Was für ein törichter Fehler.\n\nWir werden Handelsprinz Gallywix genau hier besiegen, in seinem eigenen Reich. Für die Allianz!", sourceObjective = "Tötet Handelsprinz Gallywix.", completion = "Der Gallywix, gegen den wir gekämpft haben, war nur eine Ablenkung? Ein Doppelgänger?\n\nDas treibt mich zur Weißglut. Wir waren so nah dran... Es tut mir leid, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[52261] = { id = 52261, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gallywix auf der Flucht", description = "Ich muss gestehen, ich bin etwas enttäuscht, dass wir Gallywix' gieriger Herrschaft heute kein Ende setzen konnten.\n\nAber es ist einzig und allein meine Schuld und das werde ich dem Hochkommandanten auch so berichten. Eure Leistung war so vorbildlich, wie ich es erwartet habe.\n\nIch hoffe, die Allianz wird das nicht als Grund sehen, den Glauben an die Leerenelfen zu verlieren. Wir haben so viel zu bieten.\n\nWenn Ihr bereit seid, werde ich uns ein letztes Leerenportal öffnen und uns nach Boralus zurückbringen.", sourceObjective = "Kehrt zu Hochkommandant Halford Wyrmbann an Bord der Erlösenden Winde in Boralus zurück.", completion = "Ich danke Euch, {name}. Nicht jede fehlgeschlagene Mission ist ein reiner Fehlschlag.\n\nGallywix ist nun auf der Flucht, wir haben seine Täuschung aufgedeckt und ich habe das ein oder andere über die überraschenden Taktiken vom Umbrics Leerenelfenregiment gelernt.\n\nIch habe keinen Zweifel, dass die Bewohner der Leere in Zukunft noch von hohem Wert für die Allianz sein werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[52271] = { id = 52271, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit Meersalzgeschmack" }
quests[52275] = { id = 52275, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missionsbericht: Flinkwindstation", description = "Eure Anhänger haben Euch einen Bericht über einen Angriff auf die Flinkwindstation geschickt.\n\nDarin wird erklärt, dass es ein schwer errungener Sieg war und alle bisher den Außenposten heimsuchenden Weidenbestien getötet wurden.\n\nBringt den Bericht zu Nathanos Pestrufer an Bord der Klagelied.", sourceObjective = "Bringt den Bericht über Euren Sieg zu Nathanos Pestrufer.", progress = "Gibt es Neuigkeiten über die Mission nach Drustvar?", completion = "Die Mission, in Drustvar einen zusätzlichen Stützpunkt zu errichten, war wohl von Erfolg gekrönt. Gut gemacht, {name}.\n\nIch werde Euch entsenden, damit Ihr den Bau der Befestigungsanlagen beaufsichtigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[52276] = { id = 52276, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Flinkwindstation", description = "Der Überfall, den Ihr auf die Flinkwindstation in Drustvar geplant habt, war erfolgreich. Gut gemacht.\n\nDer Außenposten ist bereit zur Übernahme.\n\nMacht Euch auf den Weg zur Flinkwindstation in Drustvar und baut dort Befestigungsanlagen.\n\nDie Flinkwindstation wird als Außenposten eine entscheidende Rolle in unserer Kampagne gegen die Allianz spielen.\n\nGeht mit Ehre!", sourceObjective = "Beansprucht die Flinkwindstation für die Horde.", completion = "Willkommen, {name}. Hier ist ein ausgezeichneter Platz für einen Außenposten! Dank Eurer Führung hat die Horde einen weiteren Stützpunkt in Drustvar!", sourceObjectiveStatus = "unverified-source-field" }
quests[52278] = { id = 52278, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abtrünniges Azerit", sourceObjective = "Besiegt Grixis Winzplopp in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[52279] = { id = 52279, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lauernde Bedrohung", description = "Wenn wir die Horde aus unserem Gebiet vertreiben wollen, muss unser Volk seine ganze Stärke aufbringen.\n\nGeht und sucht die Druiden, die Priesterinnen und unsere Schildwachen! Ruft sie zu den Waffen und seht, wie die Kaldorei zur Tat schreiten. Nur gemeinsam haben wir eine Chance, den festgefahrenen Kampf an den Wildschnellen zu gewinnen.\n\nMeldet Euch bei Malfurion Sturmgrimm, wenn Ihr fertig seid. Er wartet in Rut'theran auf unsere Flotte.", sourceObjective = "Sammelt die Streitkräfte der Kaldorei in Darnassus.", completion = "Ganz gleich, wie schlecht die Chancen stehen, wir müssen stark bleiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[52280] = { id = 52280, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit Meersalzgeschmack" }
quests[52281] = { id = 52281, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Schutz von Flinkschwinge", description = "Aye! Also, wir sind die Ersten in dieser verrückten Operation. Wir lassen uns von Flinkschwinge zur Insel der Klauen bringen.\n\nEins der Hauptschiffe der Zandalari liegt dort vor Anker. Es heißt Atem von Pa'ku, was immer das sein soll.\n\nSpringt auf Flinkschwinges Rücken, wenn Ihr abflugbereit seid. Es wird richtig gemütlich werden, wenn alle von Euch an Bord kommen.", sourceObjective = "Reitet auf Flinkschwinge zur Insel der Klauen.", progress = "Springt auf!", completion = "Wir müssen nur ein paar Bomben legen und für ein bisschen Chaos sorgen, ohne dass die Zandalari vom Festland davon wissen.\n\nIst doch einfach, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[52282] = { id = 52282, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie man ein Schlachtschiff der Zandalari versenkt", description = "Gehen wir den Angriffsplan noch einmal durch, aber denkt vor allem daran, dass die Zandalari nicht wissen dürfen, dass sich unsere gesamte Streitmacht hier befindet.\n\nWenn sie einen Stützpunkt der Allianz im Schatten ihres Reichs entdecken... würden wir auf der Stelle ausgelöscht.", sourceObjective = "Besprecht mit Halford den Plan zur Schwächung der Zandalariflotte.", progress = "Gehen wir den Plan einmal durch.", completion = "Ihr kennt den Plan, {name}. Bleibt in Deckung und schwächt die Zandalariflotte. Wenn wir diese beiden Ziele erreichen, werden wir lebendig hier herauskommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[52283] = { id = 52283, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Pa'ku sabotieren", description = "Unsere erste Aufgabe ist es, ein paar Bomben an diesen Schiffen anzubringen. Ich kümmere mich um die kleineren Schiffe, Ihr nehmt Euch die Atem von Pa'ku vor.\n\nWas immer das heißen soll.\n\nKelsey sagt, dass diese Bomben modernste Gnomtechnologie sind. Wir bringen sie an und sie kann sie jederzeit hochgehen lassen.\n\nMachen wir uns an die Arbeit, und denkt daran: Der ganze Plan funktioniert nur, wenn sie uns nicht dabei erwischen, dass wir diese Bomben legen.", sourceObjective = "Bringt 4 ferngezündete Todesbomben unter der Atem von Pa'ku an.", completion = "Meine Bomben sind alle gelegt. Ich wünschte mir trotzdem immer noch, wir könnten sie jetzt schon hochgehen lassen.\n\nSchätze, wir müssen auf den richtigen Zeitpunkt warten, um diese Dinger in die Luft zu jagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[52284] = { id = 52284, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schiffslogbücher", description = "Mogu und Zandalari arbeiten gemeinsam an Bord der Atem von Pa'ku. Sie besitzen Aufzeichnungen über die Flottenschiffe der Zandalari.\n\nWir haben fundierte Schätzungen über die Zandalariflotte angestellt. Jetzt ist es Zeit, unsere Informationen auf den neuesten Stand zu bringen.\n\nGeht da rein und holt die Marineaufzeichnungen von jedem, den Ihr an Bord des Schiffs finden könnt.\n\nOh, und nehmt diese Sprungstiefel. Ihr werdet sie brauchen, um das Schiff zu erreichen, wenn Ihr Bomben am Rumpf anbringt.", sourceObjective = "Bergt 6 Marineaufzeichnungen von Zandalari und Mogu.", progress = "Habt Ihr die Marineaufzeichnungen bekommen? Wir brauchen sie, um bessere Pläne gegen die Zandalari schmieden zu können.", completion = "Perfekt! Ich bringe diese Papiere zu Halford. Damit werden wir unsere zukünftigen Angriffe koordinieren können.", sourceObjectiveStatus = "unverified-source-field" }
quests[52285] = { id = 52285, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das vergrößerte Miniaturunterseeboot", description = "Unser nächstes Ziel ist ein Schiff, das an einem Ort uns gegenüber angedockt ist, dem Kriegshafen der Rastari.\n\nZum Glück für Euch kann ich uns alle in meinem vergrößerten Miniaturunterseeboot dort hinbringen.\n\nShandris Mondfeder und Magister Umbric sollten an der Küste des Kriegshafens der Rastari auf Euch warten.\n\nMachen wir uns auf den Weg!", sourceObjective = "Fahrt in Kelseys vergrößertem Miniaturunterseeboot zum Kriegshafen der Rastari.", completion = "Schön, dass Ihr es geschafft habt, {name}. Wir haben im Kriegshafen der Rastari viel zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[52286] = { id = 52286, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Direkt vor ihrer Nase", description = "Wir müssen mit unserem vorrangigen Ziel weitermachen, Bomben an großen Zandalarischiffen anzubringen. Eins ist im Kriegshafen angedockt.\n\nIhr wisst, was zu tun ist. Gelangt unter das Schiff, bringt die Bomben an und sorgt dafür, dass niemand sieht, wie ein... Bluttroll mit Bomben hantiert.\n\nMein Fläschchen der Unsichtbarkeit wird Euch die notwendige Tarnung bieten und Umbric glaubt, dass das Ritual Euch noch eine andere Macht verleihen wird, die Ihr anzapfen könnt.", sourceObjective = "Bringt 3 ferngezündete Todesbomben am Hauptkriegsschiff im Kriegshafen der Rastari an.", completion = "Gute Arbeit. Die Zandalari werden ein böses Erwachen haben, wenn wir ihr Flaggschiff kurz vor unserem ersten Marineüberfall in die Luft jagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[52287] = { id = 52287, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Informationsvorenthaltung", description = "Es gibt drei Meisterspione der Horde, die im Kriegshafen der Rastari stationiert sind. Sie liefern den Zandalari Informationen über die Allianzflotte.\n\nDiese Ziele müssen getötet werden. Wir können nicht zulassen, dass die Zandalari uns gegenüber im Vorteil sind, weil sie Informationen über unsere Flotte erhalten.\n\nZum Glück für uns werden mögliche Zeugen aufgrund Eurer Bluttrolltarnung annehmen, dass es sich um einen dreisten Angriff der Bluttrolle handelt.", sourceObjective = "Tötet die Meisterspione Sturmhorn, Murrblut und Gallschleuder.", completion = "Ihr habt dafür gesorgt, dass die Zandalari keine wichtigen Informationen über unsere Seestreitkräfte erhalten. Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[52288] = { id = 52288, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reise ins Leere", description = "Die Horde hat Abgesandte geschickt, die ihnen zu einem möglichen Bündnis mit den Zandalari verhelfen sollen.\n\nDiese Abgesandten sind außerdem sehr freigiebig mit Geheimnissen der Allianz, von denen die Horde Kenntnis hat. Wir müssen dem Einhalt gebieten.\n\nNehmt diese Kugel. Sie wird ein Leerenportal über dem Ziel erschaffen und es... an einen anderen Ort ziehen.", sourceObjective = "Benutzt die Portalsphäre bei 6 Abgesandten der Horde.", completion = "Gute Arbeit, das sollte die Horde und die Zandalari bei ihrem Kampf gegen die Allianz lahmlegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[52289] = { id = 52289, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Sieg ist sicher", description = "Unsere Aufgabe ist beendet. Ihr habt die Bomben auf zwei Flaggschiffen der Zandalari angebracht und Keeshan hat bei dem Rest geholfen.\n\nKehren wir zu Halford zurück. Je eher wir hier fertig sind, desto besser. Es ist viel zu riskant für uns, in unmittelbarer Nähe der Zandalari zu sein.", sourceObjective = "Trefft Halford Wyrmbann in Xibala in Zuldazar.", completion = "{name}, gerade rechtzeitig. Wir müssen hier weg.\n\nWir sind entdeckt worden.", sourceObjectiveStatus = "unverified-source-field" }
quests[52290] = { id = 52290, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Feind meines Feindes ist meine Verkleidung", description = "Ihr müsst für uns einige Ziele im Kriegshafen der Rastari töten, aber wir dürfen nicht zu erkennen geben, dass die Allianz sich hier befindet.\n\nUmbric hat ein Ritual von Nazmir entdeckt, mit dem Ihr eine Bluttrolltarnung erhaltet. Das ist furchtbar, aber es muss sein.\n\nIhr werdet das Ritual durchführen und dann mein Fläschchen der Unsichtbarkeit verwenden, um Euch in den Kriegshafen zu schleichen.\n\nWenn Ihr entdeckt werdet, werden die Zandalari und die Horde glauben, dass es sich um einen dreisten Angriff der Bluttrolle handelt... und nicht von der Allianz.", sourceObjective = "Sprecht mit Magister Umbric, um als Bluttroll verkleidet zu werden.", progress = "Ich weiß, das ist unangenehm, aber es muss sein.", completion = "Ich muss zugeben, diese Verkleidung ist verblüffend gut. Hoffen wir, dass die Zandalari denken, sie haben es mit einem Bluttroll zu tun und nicht mit der Allianz.", sourceObjectiveStatus = "unverified-source-field" }
quests[52291] = { id = 52291, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Sieg war sicher", description = "Kelsey hat die Aufzeichnungen mitgebracht, die Ihr auf der Insel der Klauen geborgen habt, aber es war zu spät.\n\nWas Ihr vor Euch seht, ist die Grals Ruf, das vermisste Zandalariflaggschiff, und sie haben uns entdeckt.\n\nWenn sie es zurück in den Hafen schaffen, wird der gesamte Zorn des Zandalariimperiums über uns hereinbrechen.\n\nWir müssen das Schiff entern und jeden Zandalari an Bord beseitigen.\n\nFalstad wird dafür sorgen, dass wir dorthin gelangen. Auf geht's.", sourceObjective = "Fliegt auf Flinkschwinge zur Grals Ruf.", completion = "Wir sind da und der Kampf hat begonnen. Beeilen wir uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[52294] = { id = 52294, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefallene Götzen", description = "Kleines Wesen, bitte... hört mir zu.\n\nIch bin Krag'wa.\n\nEinst hatte ich viele Anhänger und große Macht. Doch nun sind praktisch alle meine Anhänger fort. Die geringe Macht, die mir bleibt, ist auf verschiedene Götzen verteilt, doch diese wurden von den ketzerischen Bluttrollen gestohlen.\n\nIch bitte Euch, bringt meine Götzen zurück, damit ich wieder ich selbst werde!", sourceObjective = "Sammelt Krag'was gestohlene Götzen im Bluttrolllager in den Froschmarschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[52295] = { id = 52295, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das RIESENFLÖZ!!: Elementare als Angestellte" }
