quests[52302] = { id = 52302, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das RIESENFLÖZ!!: Der hat aber echt fette Bomben" }
quests[52305] = { id = 52305, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Umwelt gegen Veranlagung", description = "Seid gegrüßt, {name}. Ich bin Schwingenhalter Goja.\n\nIch hab von der Prüfung gehört, vor die Pa'ku Euch gestellt hat. Ich kann Euch helf'n.\n\nIch beaufsichtige dies'n Horst im Auftrag meines Loas. Un' ich hab schon viele Eier zu glorreich'n Kampftieren werd'n sehen. Es liegt noch 'n langer Weg mit viel'n Prüfungen vor Euch, aber die Freundschaft eines Pterrordax is' es allemal wert.\n\nAber der Kleine is' noch jung. Kümmert Euch um seine Bedürfnisse, solang er noch im Nest hockt. Wenn er bereit is', die Welt zu erkund'n, wird er's Euch wiss'n lassen.\n\nViel Glück, {name}.", sourceObjective = "Kümmert Euch um Kua'fon, bis er flugbereit ist.", completion = "<Kua'fon breitet seine Schwingen aus und kreischt Euch freudig an!>\n\nSkrii!", sourceObjectiveStatus = "unverified-source-field" }
quests[52306] = { id = 52306, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quako" }
quests[52307] = { id = 52307, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spirituelle Hilfe" }
quests[52308] = { id = 52308, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abgefangene Befehle", sourceObjective = "Besprecht den Plan mit den Anführern der Allianz.", progress = "Wir können uns eine Ablenkung nicht leisten... oder eine entgangene Gelegenheit.", completion = "Es ist also beschlossene Sache. Das Attentat auf Blutprinz Dreven auf hoher See wird unerwartet und demoralisierend sein und somit dem langfristigen Erfolg unserer großen Kampagne zugute kommen.\n\n<Halford Wyrmbann lächelt.>\n\nDas ist es, was ich unter \"Strategie\" verstehe.", sourceObjectiveStatus = "unverified-source-field" }
quests[52309] = { id = 52309, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sandzahn" }
quests[52310] = { id = 52310, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verderbter Wellenspringer" }
quests[52311] = { id = 52311, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schließkassette des Schmierigen", description = "Ihr habt die Schlüssel und Taelia hält uns immer noch den Rücken frei, also lasst uns zum, äh, \"Büro\" des Schmierigen gehen und die Papiere aus dieser Kassette befreien.\n\nNa los jetzt, sie ist mit dem Rest seiner Schätze auf der anderen Seite der Brücke.", sourceObjective = "Öffnet die Schließkassette des Schmierigen.", completion = "Ich bin mir sicher, dass die Informationen, die wir brauchen, in dieser Kassette sind. Aber mit den zusätzlichen Sicherheitsvorkehrungen wird mein Plan, dass Taelia einfach die Kassette aufbricht, nicht funktionieren. Wer weiß, welche anderen Sicherheitsvorkehrungen er sonst noch getroffen hat?\n\nWir müssen den letzten Schlüssel finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[52312] = { id = 52312, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Lichter löschen" }
quests[52313] = { id = 52313, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missionsbericht: Schlammfischerbucht", description = "Eure Anhänger haben Euch einen Bericht über einen Angriff auf die Schlammfischerbucht geschickt.\n\nDarin wird erklärt, dass es ein schwer errungener Sieg war und dass alle bisher den Außenposten verteidigenden Wachen getötet wurden.\n\nBringt den Bericht zu Nathanos Pestrufer an Bord der Klagelied.", sourceObjective = "Bringt den Bericht über Euren Sieg zu Nathanos Pestrufer.", progress = "Gibt es Neuigkeiten über die Mission nach Drustvar?", completion = "Die Mission, in Drustvar einen zusätzlichen Stützpunkt zu errichten, war wohl von Erfolg gekrönt. Gut gemacht, {name}.\n\nIch werde Euch entsenden, damit Ihr den Bau der Befestigungsanlagen beaufsichtigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[52314] = { id = 52314, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlammfischerbucht", description = "Der Überfall, den Ihr auf die Schlammfischerbucht in Drustvar geplant habt, war erfolgreich. Gut gemacht.\n\nDer Außenposten ist bereit zur Übernahme.\n\nMacht Euch auf den Weg zur Schlammfischerbucht in Drustvar und baut dort Befestigungsanlagen.\n\nDie Bucht wird als Außenposten eine entscheidende Rolle in unserer Kampagne gegen die Allianz spielen.\n\nHabt Eile!", sourceObjective = "Beansprucht die Schlammfischerbucht für die Horde.", completion = "Throm-Ka, {name}. Hier ist ein ausgezeichneter Platz für einen Außenposten! Dank Eurer Führung hat die Horde einen weiteren Stützpunkt in Drustvar!", sourceObjectiveStatus = "unverified-source-field" }
quests[52315] = { id = 52315, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Severus der Ausgestoßene" }
quests[52316] = { id = 52316, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meerestiere sind seltsam", sourceObjective = "Besiegt Grixis Winzplopp in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[52317] = { id = 52317, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht nehmen, nur werfen", description = "<Kua'fon legt Euch einen Trollschädel in die Hand. Er ist voller Bissspuren und ziemlich schleimig.>\n\nSkrii!\n\n<Kua'fon sieht Euch erwartungsvoll an.>", sourceObjective = "Werft Kua'fons Lieblingsschädel.", completion = "<Kua'fons Augen strahlen hell. Er verstaut seinen Trollschädel sicher unter einer Schwinge und gluckst Euch dankbar an.>\n\nSkrii.", sourceObjectiveStatus = "unverified-source-field" }
quests[52319] = { id = 52319, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missionsbericht: Windfallhöhle", description = "Eure Anhänger haben Euch einen Bericht über einen Angriff auf die Windfallhöhle geschickt.\n\nDarin wird erklärt, dass es ein schwer errungener Sieg war, Grabesmalm aber getötet wurde.\n\nBringt den Bericht zu Nathanos Pestrufer an Bord der Klagelied.", sourceObjective = "Bringt den Bericht über Euren Sieg zu Nathanos Pestrufer.", progress = "Gibt es Neuigkeiten über die Mission ins Sturmsangtal?", completion = "Die Mission, im Sturmsangtal einen zusätzlichen Stützpunkt zu errichten, war wohl von Erfolg gekrönt. Gut gemacht, {name}.\n\nIch werde Euch sofort entsenden, damit Ihr den Bau der Befestigungsanlagen beaufsichtigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[52320] = { id = 52320, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Windfallhöhle", description = "Der Überfall, den Ihr auf die Windfallhöhle im Sturmsangtal geplant habt, war erfolgreich. Gut gemacht.\n\nDer Außenposten ist bereit zur Übernahme.\n\nMacht Euch auf den Weg zur Windfallhöhle im Sturmsangtal und baut dort Befestigungsanlagen.\n\nDie Windfallhöhle wird als Außenposten eine entscheidende Rolle in unserer Kampagne gegen die Allianz spielen.\n\nGeht mit Ehre!", sourceObjective = "Beansprucht die Windfallhöhle für die Horde.", completion = "Seid gegrüßt, {name}. Hier ist ein ausgezeichneter Platz für einen Außenposten! Dank Eurer Führung hat die Horde einen weiteren Stützpunkt im Sturmsangtal!", sourceObjectiveStatus = "unverified-source-field" }
