quests[52427] = { id = 52427, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arbeitsauftrag: Schlachtflagge: Ansporn", progress = "Seid Ihr hier, um Vorräte abzuliefern?", completion = "Danke für Eure Hilfe, Schneider. Wir haben diese Schlachtflaggen wirklich dringend gebraucht." }
quests[52428] = { id = 52428, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Herz erfüllen", description = "Die Stimme Azeroths wird schwächer und schwächer. Wenn das Siegel an dieser Kammer bricht, wird ihre Seele für immer verloren sein!\n\nWir haben nur eine Chance, uns alle zu retten.\n\nAbsorbiert das Azerit in dieser Kammer in das Herz von Azeroth. Entfesselt dann die Macht des Amuletts, um den Riss in der Mitte des Siegels zu schließen.\n\nAzerit kann eine zerstörerische Macht sein, aber wenn es durch Euer Amulett kanalisiert wird, kann es sogar die Welt heilen!", sourceObjective = "Absorbiert Azerit, um das Herz von Azeroth zu verstärken.", progress = "Worauf wartet Ihr?", completion = "Das war wirklich knapp, {name}! Jetzt habt Ihr die wahre Macht des Herzens von Azeroth gesehen.\n\nEs ist aber noch ein langer Weg, bis wir die Welt geheilt haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[52430] = { id = 52430, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gar nicht so übel hier unten", sourceObjective = "Besiegt Grixis Winzplopp in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[52431] = { id = 52431, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht-Landezone", description = "Die Piraten sind rücksichtslos. Sie kommen mit Landungsbooten, um uns den Fluchtweg abzuschneiden!\n\nDie Wachen wehren sie unten am Flussufer ab, aber ich fürchte, dass sie überrannt werden, bevor ich mich und meine Familie in Sicherheit bringen kann!", sourceObjective = "Tötet Sengels die Klinge, Jaki die Gewiefte und Schädelbersterin Cotner.", completion = "Oh, ich danke Euch! Vielen, vielen Dank!", sourceObjectiveStatus = "unverified-source-field" }
quests[52432] = { id = 52432, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturmbö" }
quests[52436] = { id = 52436, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Bau der Schwarzfelle", description = "Noch haben wir nicht all unsere Truppen an die Dunkelküste versetzt, doch es sollten genug sein, um irgendwo einen Außenposten zu errichten. Ich kenne auch schon den passenden Platz.\n\nSüdlich von hier ist der Bau der Schwarzfelle. Die dort wohnenden Furbolgs sind in Hysterie verfallen. Unsere Feinde drängen von Norden her, daher ist diese Furbolgbedrohung ein Problem, das wir uns nicht leisten können.\n\nIch werde mit einem weiteren Trupp hinter die Mauer vorstoßen, während Ihr mit den Furbolgs verhandelt.", sourceObjective = "Vertreibt die Furbolgs aus dem Bau der Schwarzfelle.", completion = "Wartet nur ab, {name}, sobald wir Darnassus erobert haben, werden die Ältesten der Schwarzfelle uns dafür danken, dass wir den Frieden in ihrem Bau wiederhergestellt haben.\n\nWir müssen ihn nur vorübergehend ausleihen.", sourceObjectiveStatus = "unverified-source-field" }
quests[52437] = { id = 52437, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Beginn von etwas Gutem", description = "Während der Rest unserer Armee das Lager errichtet, solltet Ihr mir folgen. Auf meiner Rückkehr von Zoram'gar habe ich etwas... Interessantes... entdeckt.\n\nIch gebe zu, nicht einmal ich hätte einen solch glücklichen Zufall erwartet.\n\nFolgt mir, {name}. Und nehmt eine Spitzhacke mit.", sourceObjective = "Folgt Sylvanas nach Nazj'vel.", completion = "Ihr habt den Kriegshäuptling gehört. An die Arbeit!", sourceObjectiveStatus = "unverified-source-field" }
quests[52438] = { id = 52438, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Höllenritt", description = "Dieses Ding ist eins meiner besten Stücke, das könnt Ihr mir glauben, <Kleiner/Kleine>!\n\nJetzt, wo es mit dem neuesten Spielzeug aufgerüstet ist, dürfen wir keine Zeit verlieren.\n\nDer Kampf tobt an den Wildschnellen. Fliegt in meinem modifizierten Maschinchen in die Schlacht und macht ihnen die Hölle heiß!", sourceObjective = "Schließt Euch der Schlacht bei den Wildschnellen an.", completion = "Für jeden getöteten Feind erscheinen zwei neue auf dem Schlachtfeld.", sourceObjectiveStatus = "unverified-source-field" }
quests[52439] = { id = 52439, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eisenlager", description = "Solange in der Mine die Allianzbanner wehen, stellen unsere Arbeiter die Versorgung mit Eisen sicher.\n\nMit diesem Schlüssel kommt man an ihre Vorräte. Nehmt Euch, was Ihr braucht.", sourceObjective = "Benutzt den schweren Eisenschlüssel, um das Eisenlager zu öffnen.", completion = "Nun gut, das war gar nicht so schwer.", sourceObjectiveStatus = "unverified-source-field" }
quests[52440] = { id = 52440, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ressourcen rekrutieren", description = "Wenn unser Eisenvorrat nicht schwinden soll, brauchen wir ein wenig Hilfe.\n\nVersucht doch in der Mine ein paar frische Rekruten für uns zu gewinnen.", sourceObjective = "Rekrutiert 3 Hochlandarbeiter für die Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[52443] = { id = 52443, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der letzte Stützpunkt", description = "In Zandalar haben wir zwei wichtige Stützpunkte errichtet. Jetzt wird es Zeit für einen dritten.\n\nSchauen wir doch mal auf den Schlachtplan, sobald Ihr bereit seid.", sourceObjective = "Verwendet die Kampagnenkarte von Zandalar, um den letzten Stützpunkt auszuwählen.", completion = "Seid Ihr bereit? Dann an die Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[52444] = { id = 52444, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der letzte Stützpunkt", description = "In Kul Tiras haben wir zwei wichtige Stützpunkte errichtet. Jetzt wird es Zeit für einen dritten.\n\nSchauen wir doch mal auf den Schlachtplan, sobald Ihr bereit seid.", sourceObjective = "Verwendet die Kampagnenkarte von Kul Tiras, um den letzten Stützpunkt auszuwählen.", completion = "Ich gehe davon aus, dass Ihr gut vorbereitet seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[52445] = { id = 52445, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tol Dagor: Der vierte Schlüssel", description = "He, wartet mal. Ich kenne die Art Schlüssel, die wir für unser viertes Schloss brauchen. Das hier ist dieselbe Art Schloss, wie es von Aschenwind & Co. verwendet wird. Es ist mit einfachen Hakendietrichen nicht zu öffnen, aber mit einem komplizierten Dietrich geht's. Im Arsenal von Tol Dagor hing ein Satz an der Wand. In dem Zustand, in dem wir es hinterlassen haben, dürfte es ein Leichtes sein, den zu holen.\n\nTaelia und ich werden die Kassette ins Büro des Hafenmeisters in Sicherheit bringen.\n\nIhr geht nach Tol Dagor und holt den letzten Schlüssel!", sourceObjective = "Betretet den Dungeon von Tol Dagor, holt den Aschenwinddietrich und tötet Aufseher Korgus. Kehrt dann zu Finn Schönwind im Büro des Hafenmeisters in Boralus zurück.", progress = "Ich wusste, dass es Euch keine Probleme bereiten würde, den letzten Schlüssel zu beschaffen, {name}!", completion = "Nun, Ihr habt Eure Antwort. Jaina wurde nach Schicksalsend gebracht.", sourceObjectiveStatus = "unverified-source-field" }
quests[52446] = { id = 52446, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwester Absinthia" }
quests[52447] = { id = 52447, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freiraum zum Wachsen", description = "Ach, über den Kleinen müsst Ihr Euch nich' sorg'n.\n\nManche Tiere lern'n etwas langsamer und so is' das auch bei Kua'fon.\n\nHelft ihm bis dahin beim Wachs'n. Füttert ihn gut, behütet ihn un' stärkt Eure Bindung. Er wird Euch schon zeig'n, wenn er für 'nen neuen Versuch bereit is'.", sourceObjective = "Kümmert Euch um Kua'fon, bis er für einen zweiten Flugversuch bereit ist.", completion = "<Kua'fon windet sich ängstlich und blickt Euch mit einem goldenen Auge an.>\n\nSkrii?", sourceObjectiveStatus = "unverified-source-field" }
quests[52449] = { id = 52449, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die geheimnisvolle Insel", description = "Schicksalsend, der Name sagt alles. Dorthin verfrachtet man die allerschlimmsten Verbrecher. Niemand kehrt je zurück.\n\nEs tut mir leid, dass Lady Katherine das erfahren muss, doch wenigstens muss ich es ihr nicht sagen.\n\n<Finn übergibt Euch das Schriftstück mit ernstem Blick.>\n\nIch bin mir sicher, sie wird von den Neuigkeiten wissen wollen, auch wenn sie Schlechtes verheißen.", sourceObjective = "Erstattet Katherine Prachtmeer in Boralus Bericht.", completion = "Schicksalsend! Gnädige Gezeiten, ich hoffte so sehr, dass man sie nicht dort hinbringen würde... aber natürlich musste es so kommen.\n\nEs spielt keine Rolle. Ich muss weiter voranschreiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[52450] = { id = 52450, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Vereinigung von Kul Tiras", sourceObjective = "Das Volk von Kul Tiras ist vielseitig und äußerst fähig. Solange es der Allianz treu ist, hat die Horde keine Chance, uns aufzuhalten.\n\nJetzt kommt die echte Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[52451] = { id = 52451, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Vereinigung von Zandalar", sourceObjective = "Das Volk von Zandalar ist vielseitig und äußerst fähig. Solange es der Horde treu ist, hat die Allianz keine Chance, uns aufzuhalten.\n\nJetzt kommt die echte Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[52452] = { id = 52452, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herrin der Gesänge Dadalea" }
quests[52453] = { id = 52453, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine aussichtslose Hoffnung", description = "<Lady Katherine mahlt mit den Kiefern.>\n\nIch weigere mich, zu glauben, dass ich zu spät komme.\n\nNiemand ist je aus Schicksalsend zurückgekehrt, aber wenn jemand das überleben kann, dann mit Sicherheit meine Jaina.\n\nBegebt Euch ins Sturmsangtal und klärt die Reise nach Schicksalsend mit den Gezeitenweisen ab. Ihr solltet am besten mit Bruder Pike anfangen.\n\nBeeilt Euch, {name}.", sourceObjective = "Geht nach Sturmsang und sprecht mit Bruder Pike an der Krakenspanne.", completion = "Jaina Prachtmeer wurde nach Schicksalsend geschickt und ihre Mutter möchte sie retten?\n\nDann müssen wir umgehend handeln, wenn wir auch nur die geringste Aussicht haben wollen, ihr Leben zu retten.", sourceObjectiveStatus = "unverified-source-field" }
quests[52454] = { id = 52454, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freihafen: Schreckenskapitän Vandegrimm" }
quests[52455] = { id = 52455, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unverwüstlich", sourceObjective = "Besiegt Grixis Winzplopp in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[52456] = { id = 52456, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freihafen: Kriegsbewährte Galeere" }
quests[52458] = { id = 52458, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freihafen: Piratendublonen" }
quests[52459] = { id = 52459, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wirbelschwinge" }
quests[52462] = { id = 52462, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Haufen Schrott", description = "Hallo, <mein Freund/meine Liebe>. Interesse an einem Exklusivbericht über die schärfste neue Entwicklung des Jahrhunderts?\n\nDas ist die Schrott-o-matik 1000, und dieses Gerät kann Eure Produktionskapazität bei der Herstellung von Rüstungen, Waffen oder anderen nützlichen Abenteurerutensilien verdreifachen, ach was, sogar verVIERfachen!\n\nHier, nehmt doch mal diese Hose und benutzt die Schrott-o-matik. Ihr werdet es schnell begreifen.", sourceObjective = "Benutzt die Schrott-o-matik 1000 mit der zerschlissenen Hose.", progress = "Diese Maschine wird alles verändern!", completion = "Und einfach so, ratz, fatz, seid Ihr wieder am Start! All die Materialien, die bei der Herstellung des Objekts verwendet wurden, werden durch die Schrott-o-matik 1000 wieder nutzbar.\n\nNun gut, nicht ALLE Materialien. Aber es ist immer noch besser, als alles zu verlieren, oder?\n\nOh, und achtet auf das Vorkommen von Explusom. Das ist ein magisches Material, das wir beim Wiederverwertungsprozess als Nebenprodukt entdeckt haben.\n\nEs ist ziemlich mächtig und entsteht nur, wenn man das gute Zeug verwertet.", sourceObjectiveStatus = "unverified-source-field" }
quests[52463] = { id = 52463, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haegol der Hammer" }
quests[52464] = { id = 52464, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oska der Blutige" }
quests[52471] = { id = 52471, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein ziemlich großer Kadaver", sourceObjective = "Besiegt Grixis Winzplopp in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[52472] = { id = 52472, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Na'logo muss wandern", description = "Hallo, {name}! Jeder Tortollaner hört in seiner Kindheit Geschichten über Na'logo, einen Tortollaner, der viele Abenteuer erlebt hat. Diese Geschichten fordern den Verstand der jungen Tortollaner, die ausknobeln möchten, wie wohl Na'logo seinen Weg durch die verschiedenen Abenteuer gefunden hat.\n\nMöchtet Ihr es mal probieren?", sourceObjective = "Lernt, wie man Na'logo führt.", sourceObjectiveStatus = "unverified-source-field" }
quests[52473] = { id = 52473, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Flotte versenken", description = "Jetzt gilt es, {name}. Wir haben die Horde so stark geschwächt, dass wir für einen wagemutigen Schlag gegen Zuldazar bereit sind.\n\nMit der Hilfe der Dunkeleisenzwerge halten sich unsere Truppen in Zuldazar weiterhin im Verborgenen. Das gibt uns die Chance auf einen Überraschungsschlag.\n\nReist nach Zuldazar. Dort sammeln wir unsere Streitkräfte für einen koordinierten Schlag, um ihre Hafenverteidigung zu schwächen.", sourceObjective = "Sprecht mit Großadmiralin Jes-Tereth, um nach Zuldazar zu reisen.", completion = "Alle sind versammelt. Wir sollten beginnen, ohne weitere Zeit zu verschwenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[52474] = { id = 52474, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wilderer Jannes" }
quests[52475] = { id = 52475, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo die Adler jagen" }
quests[52476] = { id = 52476, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pilzkönig" }
quests[52477] = { id = 52477, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Ayame", description = "Gesucht: Wegen der Tode von zwölf Pilgern und ihrer Eskorte nach Torgas Ruh ist eine Belohnung auf den Kopf der großen Schlange Ayame ausgesetzt. \n\n- Korkusch", sourceObjective = "Jagt Ayame und nehmt ihren Kopf.", progress = "Ja, ich habe das Plakat angebracht. Habt Ihr etwas für mich?", completion = "Es freut mich, dass die Schlange endlich bekommen hat, was sie verdient!\n\nHier ist Eure Belohnung, die habt Ihr wahrlich verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[52478] = { id = 52478, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missionsbericht: Kuppensteigweide", description = "Eure Anhänger haben Euch einen Bericht über einen Angriff auf die Kuppensteigweide geschickt.\n\nDarin wird erklärt, dass es ein schwer errungener Sieg war und dass die Verteidiger des Sturmsangtals getötet wurden.\n\nBringt den Bericht zu Nathanos Pestrufer an Bord der Klagelied.", sourceObjective = "Bringt den Bericht über Euren Sieg zu Nathanos Pestrufer.", progress = "Gibt es Neuigkeiten über die Mission ins Sturmsangtal?", completion = "Die Mission, im Sturmsangtal einen zusätzlichen Stützpunkt zu errichten, war wohl von Erfolg gekrönt. Gut gemacht, {name}.\n\nIch werde Euch sofort entsenden, damit Ihr den Bau der Befestigungsanlagen beaufsichtigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[52479] = { id = 52479, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kuppensteigweide", description = "Der Überfall, den Ihr auf die Kuppensteigweide im Sturmsangtal geplant habt, war erfolgreich. Gut gemacht.\n\nDer Außenposten ist bereit zur Übernahme.\n\nMacht Euch auf den Weg zur Kuppensteigweide im Sturmsangtal und baut dort Befestigungsanlagen.\n\nDie Kuppensteigweide wird als Außenposten eine entscheidende Rolle in unserer Kampagne gegen die Allianz spielen.\n\nGeht mit Ehre!", sourceObjective = "Erobert die Kuppensteigweide für die Horde.", completion = "Seid gegrüßt, {name}. Hier ist ein ausgezeichneter Platz für einen Außenposten! Dank Eurer Führung hat die Horde einen weiteren Stützpunkt im Sturmsangtal!", sourceObjectiveStatus = "unverified-source-field" }
quests[52480] = { id = 52480, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Ayame", description = "Gesucht wird ein gut ausgerüsteter Schädlingsbekämpfer.\n\nEine große Schlange treibt nördlich der Siegesfeste ihr Unwesen. \n\nFür den Kopf des Schädlings steht eine Belohnung bereit.\n\n- Garrick Schwarzstahl", sourceObjective = "Jagt Ayame und nehmt ihren Kopf.", progress = "Habt Ihr etwas für mich?", completion = "Ah! Gut! Seit ich das Ding zum ersten Mal gesehen habe, konnte ich nachts kein Auge mehr zukriegen.\n\nHier ist Eure Belohnung, die habt Ihr Euch wahrlich verdient!", sourceObjectiveStatus = "unverified-source-field" }
quests[52481] = { id = 52481, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aus Mythen und Märchen", description = "Wenn Jaina wirklich in den Verseuchten Landen in der Falle sitzt, könnte das bedeuten, dass wir noch nicht zu spät sind! Wir müssen nur einen Weg hinein finden...\n\nWir müssen die Hilfe von Luzilla Kronsteig gewinnen. Die Legenden, die sich um diesen Ort ranken, sind tief in Drustvars Kultur verwurzelt. Wenn jemand mehr darüber weiß, dann sie.\n\nIch werde einen Raben vorausschicken, damit sie sich vorbereiten und so viel Wissen wie möglich zusammentragen kann. Begebt Euch eilends nach Aroms Wehr!", sourceObjective = "Trefft Luzilla Kronsteig bei Aroms Wehr in Drustvar.", completion = "Ich kann nicht glauben, dass Ihr absichtlich in die Verseuchten Lande gehen wollt. Den Legenden zufolge ist es ein grässlicher Ort, der nur existiert, um Qualen und Pein zu bereiten.\n\nIch kann mir keinen Schatz vorstellen, der es wert wäre, so einen Ort zu betreten.", sourceObjectiveStatus = "unverified-source-field" }
quests[52482] = { id = 52482, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der alte Bär", description = "Ich kann Eure Meinung nicht ändern, was? Nun gut, vielleicht weiß ich, wo Ihr Eure Antworten finden könnt. \n\nWeit oben in den Bergen ist eine verborgene Nische, die unfassbar grün bewachsen ist. Dort lernen die Druiden von Kul Tiras die alten Wege der Drust aus den Zeiten von Gorak Tul.\n\nIhr Anführer ist ein großer Bär namens Ulfar. Ich weiß nicht viel über ihn, doch kaum jemand weiß mehr über Magie der Drust.\n\nVom Hochwegpass zweigt ein Weg zu seiner Höhle ab. Viel Glück, <Inquisitor/Inquisitorin>.", sourceObjective = "Sprecht mit Ulfar in Ulfars Höhle.", progress = "Ja?", completion = "Vergebt mein Zögern, Festländer. Wie mir scheint, sind Thros' Lakaien nicht mehr nur auf ihr eigenes Reich beschränkt.\n\nIch werde Euch helfen, die Schwelle in die Verseuchten Lande zu überschreiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[52483] = { id = 52483, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alptraumfänger", description = "Die Bildnisse, die Gorak Tuls Anhänger angefertigt haben, wurden nicht aus Holz, sondern aus den Knochen und Sehnen ihrer Feinde erschaffen. Das ist Euer erstes Ziel.\n\nReist nach Gol Osigr, wo die uralten Drust aus ihrem Schlaf erwacht sind. Die Knochen hier gehörten Gorak Tuls größten Kriegern, die bei der letzten Schlacht gegen den ersten Lord Kronsteig an seiner Seite standen.\n\nIhre Knochen verströmen Hass und Wut. Das wird unseren Zweck gut erfüllen.", sourceObjective = "Sammelt 4 intakte Drustknochen und 9 uralte Sehnen von Drustskeletten in Gol Osigr.", progress = "Habt Ihr die Materialien?", completion = "Den Hass, der von diesen Knochen ausgeht, kann ich geradezu spüren. Die werden ihren Zweck erfüllen.", sourceObjectiveStatus = "unverified-source-field" }
quests[52484] = { id = 52484, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vergrabene Macht", description = "Seit Menschengedenken haben die Drust Runen genutzt, um ihre Magie zu formen. Auch bei den Zaubern von Gorak Tul und seinesgleichen war dies so. Damit Euer Bildnis seine Funktion erfüllt, benötigt Ihr derartige Runen.\n\nVermutlich finden sich noch welche am Ort seines letzten Kampfes, tief unter Asche und Schnee vergraben.\n\nNehmt diesen Stein. Er wurde mit der Macht der Dornsprecher erfüllt und wird auf Tuls Zauber reagieren. Damit könnt Ihr die Runen finden, egal, wie tief sie nach den Jahren begraben liegen.", sourceObjective = "Benutzt den Wünschelstein, um 6 Drustrunensteine in Gol Osigr zu sammeln.", progress = "Was habt Ihr unter dem Schnee von Gol Osigr entdeckt?", completion = "Diese Runensteine pulsieren noch immer mit der verzerrten Energie von Gorak Tuls Magie. Das ist genau, was Ihr braucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[52485] = { id = 52485, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fokus des Hasses", description = "Das Bildnis benötigt einen zentralen Fokus. Der Zirkel nutzt für diesen Zweck gerne Tierschädel, doch für Eure Aufgabe benötigt Ihr etwas Stärkeres.\n\nKorvash war ein treuer Leutnant von Gorak Tul sowie ein mächtiger Zauberer. Er erlag in der Schlacht von Aroms Wehr. Seine Knochen liegen noch immer dort, nach all den Jahren tief begraben.\n\nFindet sie und holt seinen Schädel.", sourceObjective = "Beschafft Korvashs Schädel von Korvash in Gol Osigr.", progress = "Habt Ihr Korvashs Knochen gefunden?", completion = "Korvashs Schädel wird einen wahrlich mächtigen Fokus ergeben, doch die Zeit hat ihm seine natürliche Macht entzogen.\n\nEs sind noch mehr Schritte notwendig, um das Ritual vorzubereiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[52486] = { id = 52486, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Kronsteiganwesen: Den Herzbann absorbieren", description = "Der Schädel, den Ihr Korvash abgenommen habt, muss in Gorak Tuls Magie reifen. Erst dann kann er die notwendige Macht entwickeln, um die Lücke nach Thros zu überbrücken. Ihr müsst ihn zu einem Quell seiner Macht bringen und ihn dort die Magie absorbieren lassen.\n\nSo eine Quelle findet Ihr im Kronsteiganwesen - dem Machtzentrum des Zirkels. Ihr Anführer hat sich dort so ungehindert an Tuls Macht bedient, dass diese geradezu von den Wänden verströmt wird.\n\nBringt Korvashs Schädel ins Herz des Anwesens und lasst ihn sich laben. Dann wird das Bildnis vervollständigt sein.", sourceObjective = "Stärkt Korvashs Schädel in den Tiefen des Kronsteiganwesens.", completion = "Das Ding hier ist der Schlüssel, um das Tor zu öffnen?\n\nUnd Ihr wollt das wirklich durchziehen?", sourceObjectiveStatus = "unverified-source-field" }
quests[52487] = { id = 52487, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die Dunkelheit", description = "Ich habe nicht geglaubt, dass Ihr einen Weg finden würdet. Obwohl ich inzwischen sagen muss, dass es mich nicht überraschen würde, wenn Ihr das Unmögliche wirklich möglich macht.\n\nIch schätze, jetzt bleibt nur noch, dem Blutroten Wald die Stirn zu bieten und zu sehen, ob es funktioniert.\n\nKatherine hat mir allerdings befohlen, ihr erst eine Nachricht zu schicken, wenn Ihr einen Weg zu Jaina gefunden habt. Ihr könnt ihr mithilfe eines unserer Falken eine Botschaft senden.", sourceObjective = "Sprecht mit Fähnrich Josen, um eine Nachricht an Katherine zu schicken. Dann trefft Euch mit ihr bei Gol Inath im Blutroten Wald.", progress = "Wir sind bis hierher gekommen. Es gibt keinen Weg zurück.", completion = "Anscheinend funktioniert die Magie des Bildnisses, doch ich glaube, uns entgeht irgendetwas.", sourceObjectiveStatus = "unverified-source-field" }
quests[52488] = { id = 52488, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Renitente Runen", description = "Ganz gleich, was mit diesem Bildnis ist, ich glaube nicht, dass es ohne unsere Hilfe das Tor öffnen wird.\n\nDiese Runen müssen der Schlüssel sein. Es muss einen Weg geben, wie wir sie benutzen können, um das Bildnis zu aktivieren.", sourceObjective = "Löst das Runenrätsel, um das Drustbildnis in Gol Inath zu aktivieren.", completion = "Bemerkenswert! Gestern glaubte ich noch, dass es diesen Ort nur in Erzählungen und Legenden gibt und jetzt stehe ich nur einen Schritt davon entfernt...\n\nIch hoffe nur, dass wenigstens einige der Geschichten übertrieben waren...", sourceObjectiveStatus = "unverified-source-field" }
quests[52489] = { id = 52489, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Jagd auf Blutprinz Dreven", sourceObjective = "Reitet auf Flinkschwinge, um Falstad und Shandris zum Großen Meer zu begleiten.", completion = "Das miserable Wetter bietet uns etwas Deckung. Jede dicke Wolke und jeder Regentropfen zählen als Verbündeter.\n\n<Shandris Mondfeder grinst.>\n\nSo gesehen sind wir der Horde zahlenmäßig überlegen. Sie haben keine Chance.", sourceObjectiveStatus = "unverified-source-field" }
quests[52490] = { id = 52490, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinter feindlichen Schiffen", sourceObjective = "Durchsucht die Klagelied nach Lebenszeichen von Blutprinz Dreven.", completion = "Ha! Nach der Tracht Prügel wird Nathanos heulend zurück in Sylvanas Schoß kriechen!\n\nHabt Ihr Blutprinz Dreven gefunden?", sourceObjectiveStatus = "unverified-source-field" }
quests[52491] = { id = 52491, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breitseitenbambule", description = "<Die Schiffskanonen sind im Moment über das Wasser hinweg auf das andere Schiff der Verlassenen gerichtet.\n\nAllerdings scheint es, als ob die Besatzung sie nicht mit Schwarzpulver oder Kanonenkugeln geladen hat... Wahrscheinlich, um unbeabsichtigte Schüsse zu vermeiden, solange sie hier vor Anker liegen.\n\nJa, es wäre wirklich schade, wenn \"versehentliches\" Kanonenfeuer das andere Schiff beschädigte.>", sourceObjective = "Holt Euch Schießpulver, Kanonenkugeln und eine Fackel und feuert die Kanonen ab.", progress = "Habt Ihr etwas Interessantes da unten im Schiff gefunden?", completion = "Ich wünschte, Ihr hättet die Panik der Mannschaft sehen können, als Ihr die Kanonen abgefeuert habt! Es war zum Totlachen!\n\nSo machen die Wildhämmer das!", sourceObjectiveStatus = "unverified-source-field" }
quests[52492] = { id = 52492, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wildhämmerspezialität", description = "Nun, wenn Ihr Blutprinz Dreven nicht auf Eurem Schiff gefunden habt, dann versteckt er sich wohl auf dem anderen.\n\nIch kann Euch dort hinbringen, aber die Horde weiß jetzt, dass wir hier sind. Was meint Ihr, sollen wir ein paar Ablenkungsmanöver starten, damit sie beschäftigt sind, während wir Dreven aufspüren?\n\nMeinen Wildhämmern juckt es in den Fingern, ihre Hämmer fliegen zu lassen. Wollt Ihr bei der ersten Runde mitmachen?", sourceObjective = "Schließt Euch Falstad und Flinkschwinge bei einem Bomberangriff auf die Hordenschiffe an.", completion = "Er ist hier.", sourceObjectiveStatus = "unverified-source-field" }
quests[52493] = { id = 52493, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine unnatürliche Mannschaft", description = "Blutprinz Dreven ist hier und die Lage ist noch schlimmer, als wir befürchtet hatten.\n\nDas Monster bildet weitere San'layn aus. Jeder Neophyt, den Ihr auf diesem Schiff seht, ist ein zukünftiger Blutprinz Dreven.\n\nEs darf nicht passieren, dass sich seine ruchlosen Praktiken in der Horde verbreiten. Wir werden die San'layn jetzt mit Stumpf und Stiel ausmerzen.", sourceObjective = "Tötet 12 Besatzungsmitglieder der Horde an Bord der Blutschwall.", progress = "Jeder San'layn muss heute fallen, sonst werden wir sie nie los.", completion = "Das reicht jetzt. Wir müssen unsere Bemühungen auf Blutprinz Dreven konzentrieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[52494] = { id = 52494, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garstige Kristalle garstiger Leute", description = "Blutprinz Dreven und seine Anhänger saugen Macht aus bluterfüllten Kristallen, um ihre unheiligen Fähigkeiten zu verstärken.\n\nWir sollten sie zerstören und so Dreven schwächen, bevor wir gegen ihn kämpfen. Zerstört so viele Kristalle, wie Ihr finden könnt.", sourceObjective = "Zerstört 5 Kristalle der San'layn.", completion = "Gut. Das sollte Blutprinz Dreven lange genug schwächen, damit wir ihn töten können.", sourceObjectiveStatus = "unverified-source-field" }
quests[52495] = { id = 52495, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beendet die Bedohung durch die San'layn", description = "Blutprinz Dreven hat sich auf dem untersten Deck seines Schiffs verbarrikadiert. Dort sitzt er in der Falle.\n\nGlaubt nicht, dass es dadurch für uns einfacher wird. Ein in die Enge getriebenes Tier ist gefährlicher als eines in Freiheit. Aber wir können ihn töten, vorausgesetzt, wir haben den Willen und die Weisheit.\n\nFolgt mir. Ich werde die Barriere durchbrechen, die sein Versteck schützt, dann treten wir ihm gemeinsam gegenüber.", sourceObjective = "Tötet Blutprinz Dreven.", completion = "<Shandris blickt zum Himmel und spricht bedrückt.>\n\nAnde'thoras-ethil, Schwestern. Shaha lor'ma.", sourceObjectiveStatus = "unverified-source-field" }
quests[52496] = { id = 52496, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine saubere Flucht", sourceObjective = "Kehrt nach Boralus zurück und erstattet Hochkommandant Halford Wyrmbann Bericht.", completion = "Heute habt Ihr der Allianz und ganz Azeroth einen guten Dienst erwiesen, {name}.\n\nDie Welt, in der wir heute einschlafen, ist eine bessere als die, in der wir heute erwacht sind. Mehr kann man von uns nicht verlangen.\n\nFür die Allianz!", sourceObjectiveStatus = "unverified-source-field" }
quests[52505] = { id = 52505, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Dornen abschneiden" }
quests[52506] = { id = 52506, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Stacheln abstumpfen" }
quests[52507] = { id = 52507, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klebrige Sauerei" }
quests[52508] = { id = 52508, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritualgegenstände", description = "Für das Ritual, das uns nach Schicksalsend bringt, werde ich Unterstützung brauchen. Und um diese zu leisten, werdet Ihr die passenden Gegenstände und Kleidungsstücke benötigen.\n\nNormalerweise hätte ich ja Zugriff auf all solche Dinge, doch die Unruhen halten mich und viele meiner Brüder und Schwestern von ihnen fern. Die gefallenen Gezeitenweisen der Spanne haben jedoch alles, was Ihr benötigt.\n\nSammelt ein Ritualmesser, eine Laterne und Roben von den Gefallenen und den sogenannten Propheten.", sourceObjective = "Sammelt ein Ritualmesser, eine Rituallaterne und Ritualroben von den gefallenen Kielwächtern und Abgrundpropheten im Gewitterrand.", progress = "Mir wird ganz warm ums Herz, wenn ich sehe, dass diese Sachen noch einmal einen guten Zweck erfüllen.", completion = "Wunderbar. Das ist mehr als nur ein Kostüm, all diese Sachen sind ein wichtiger Teil unserer Traditionen. Damit das Ritual funktioniert, müsst Ihr die Rolle so vollständig wie möglich annehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[52509] = { id = 52509, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Stärke des Sturms", description = "Das Ritual, das ich durchführen muss, ist auf einer Schriftrolle niedergeschrieben. Um Zugriff darauf zu erhalten, müsst Ihr die dunklen Energien durchdringen, mit denen die gefallenen Gezeitenwesen sie eingehüllt haben. Dafür benötigt Ihr die Macht des Sturms.\n\nDieses Relikt kann genutzt werden, um den versklavten Elementaren gereinigte Macht zu entziehen. So erhaltet Ihr nicht nur, was wir benötigen, sondern befreit auch die Elementargeister von der Verderbnis.\n\nBesiegt die versklavten Elementare und zieht ihre Macht in das Relikt.", sourceObjective = "Sammelt Sturmwogenpartikel von besiegten Elementaren.", completion = "Gut gemacht, {name}. Der Stab enthält nun die Macht der Elementare. Die werdet Ihr für das Bevorstehende brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[52510] = { id = 52510, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schrein des Sturms: Das fehlende Ritual", description = "Das Ritual, das uns sicheres Geleit nach Schicksalsend verschafft, ist ein sorgsam gehütetes Geheimnis, um Neugierige davor zu schützen, dort hinzugelangen und dasselbe Schicksal zu erleiden, wie die Verurteilten. Ich habe es noch nie durchgeführt, doch es gibt eine Schriftrolle, die es erklärt.\n\nSie befindet sich im Schrein des Sturms. Um die Schriftrolle zu erhalten, müsst Ihr den ermächtigten Stab nutzen und die dunkle Energie um sie herum bannen.\n\nBesorgt das Ritual des sicheren Geleits und bringt es zu mir.", sourceObjective = "Geht in den Schrein des Sturms, bergt das Ritual des sicheren Geleits und besiegt Vol'zith den Flüsterer.", progress = "Ist es Euch gelungen, das Ritual des sicheren Geleits zu beschaffen?", completion = "Gut! Wenn wir Lady Jaina retten wollen, ist Eile geboten. Ich habe schon alle mir möglichen Vorbereitungen getroffen. Lasst mich nur kurz das Ritual durchlesen, dann können wir beginnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[52511] = { id = 52511, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Öffnen des Weges", description = "Hm. Das Ritual ist ein wenig... kompliziert. Aber egal, gemeinsam werden wir es schaffen.\n\nIch beginne mit der Kanalisierung. Ihr müsst dabei die Runen in der richtigen Reihenfolge aktivieren. Ich lasse die Schriftrolle hier, falls Ihr nachsehen müsst.", sourceObjective = "Schließt das Ritual ab.", completion = "Von hier aus sollten wir Schicksalsend erreichen. Hoffentlich noch rechtzeitig.", sourceObjectiveStatus = "unverified-source-field" }
quests[52512] = { id = 52512, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schicksalsend", description = "Schicksalsend ist ein chaotischer Ort. Die See schäumt, Donner durchdringt die Luft. Einst versuchten wir, uns dort niederzulassen, doch jede Siedlung verschwand im Nebel und keine Seele wurde je wiedergesehen. Die Insel will keine Bewohner.\n\nNun schicken wir nur unsere Niederträchtigsten dorthin. Sie kehren nie zurück, aber niemand weiß, weshalb.\n\nWenn wir Jaina finden und retten, wäre es das erste Mal, dass so etwas gelingt. Ich hoffe, dass wir nicht zu spät sind.", sourceObjective = "Reist nach Schicksalsend und sucht nach Anzeichen von Jaina.", completion = "Es sah so aus, als ob Ihr die Insel für einen ganz kurzen Moment verlassen habt und dann wieder mit dieser Kreatur aufgetaucht seid. Vielleicht ist Jaina dort, wo sie herkam.\n\nLady Katherine sollte von dieser Entwicklung erfahren.", sourceObjectiveStatus = "unverified-source-field" }
quests[52513] = { id = 52513, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Dunkelheit verloren", description = "Wenn die Leute an einen anderen Ort gezogen werden, würde das erklären, warum niemand je zurückgekehrt ist. Ich werde dies als Zeichen nehmen, dass Jaina noch gerettet werden kann.\n\nKehrt schleunigst zu Lady Katherine zurück! Sie wird von dieser Entwicklung wissen wollen.", sourceObjective = "Kehrt zu Katherine Prachtmeer in Boralus zurück.", completion = "Die Verseuchten Lande? Aber... Ich dachte, das wäre nur eine Legende, um Kindern Angst einzujagen.\n\nMeine Tochter... Was habe ich dir nur angetan?", sourceObjectiveStatus = "unverified-source-field" }
quests[52544] = { id = 52544, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kriegsvorrat", description = "{name}. Lasst uns reden.\n\nWir werden diesen Krieg nicht gewinnen, nur weil wir die Kul Tiraner an unserer Seite haben. Irgendwann müssen wir die Horde zermalmen.\n\nIhr werdet mit mir eine Expedition leiten... Wir werden die Operationen der Horde in Zandalar stören. Aber zuerst brauchen wir Ressourcen.", sourceObjective = "Sammelt 100 Kriegsressourcen. Kriegsressourcen können von vielen unterschiedlichen Quellen beschafft werden, darunter über Quests und Schatztruhen.", completion = "Ihr habt genug Ressourcen gesammelt, um mit dem Angriff auf Zandalar zu beginnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[52545] = { id = 52545, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Royston braucht Hilfe!" }
